css.value:
* {
	font-feature-settings: 'clig' off, 'liga' off;
	font-family: Lato;
	font-size: 1rem;
	font-style: normal;
	font-weight: 400;
	line-height: normal;
}

script.inlineScript:
/**
 * @param {params} params
 * @param {api} params.api
 * @param {TransformApiHelpers} params.helpers
 */
function evaluateProperty({
    api,
    helpers
}) {
    let header = {
        label: api.item.value.question,
        variant: "secondary",
        size: "md",
    };

    return header;
}
